  use ExUnit.Case, async: false

  alias JoobQ.Worker.{Acker, Heartbeater, Poller, Redact}

  @secret "lease-s3cr3t"

  defp config, do: JoobQ.Config.new!(url: "https://x", token: "t0ken", queues: ["mail"])

  test "a worker process's status shows counts and message tags, never tokens, payloads or outputs" do
    job = %JoobQ.Job{lease_token: @secret, payload: %{"password" => "hunter2"}}
    item = %{"token" => @secret, "outcome" => "complete", "output" => "hunter2"}

    poller = %{
      config: config(),
      buffer: :queue.from_list([job]),
      running: %{make_ref() => %{job: job}}
    }

    acker = %{
      config: config(),
      queue: :queue.from_list([item]),
      waiting: :queue.new(),
      sending: {make_ref(), [item]}
    }

    message = {:settle, item}
    crash = %FunctionClauseError{args: [item]}
    reason = {crash, [{Acker, :pick, [item], [file: ~c"a.ex", line: 1]}]}
    {:stop, guarded, _state} = Redact.guard(%{}, fn -> raise "boom #{@secret}" end)

    for {module, state} <- [{Poller, poller}, {Acker, acker}, {Heartbeater, {config(), self()}}] do
      status =
        module.format_status(%{state: state, message: message, queue: [message], reason: reason})

      printed = inspect(status) <> IO.iodata_to_binary(:io_lib.format(~c"~p", [status]))
      refute printed =~ @secret
      refute printed =~ "hunter2"
      refute printed =~ "t0ken"
      assert status.message == {:settle, :redacted}

      # The stop of a guarded callback, as a crash report shows it: its class and frames, not the message.
      %{reason: shown} = module.format_status(%{state: state, reason: guarded})
      assert {:crashed, RuntimeError, [_frame | _more]} = shown
      refute inspect(shown) =~ @secret
    end

    assert Redact.tag(:renew) == :renew
    assert Redact.tag([@secret]) == :redacted
  end

  test "a crash reason keeps classes, functions, arities and lines, never arguments" do
    stack = [{Acker, :pick, [%{"token" => @secret}], [file: ~c"a.ex", line: 3, error_info: %{}]}]

    key_error = %KeyError{key: @secret}

    assert Redact.reason({key_error, stack}) ==
             {KeyError, [{Acker, :pick, 1, [file: ~c"a.ex", line: 3]}]}

    assert Redact.reason({:function_clause, stack}) ==
             {:function_clause, [{Acker, :pick, 1, [file: ~c"a.ex", line: 3]}]}

    badmatch = {:badmatch, @secret}
    assert Redact.reason({badmatch, []}) == {Redact.tag(badmatch), []}
    assert Redact.tag(badmatch) == {:badmatch, :redacted}
    assert Redact.reason(:normal) == :normal

    # A guarded callback's stop keeps its class and frames.
    {:stop, stop, _state} = Redact.guard(%{}, fn -> raise "boom" end)
    assert {:crashed, RuntimeError, [_frame | _more]} = Redact.reason(stop)

    # Any process may stop with that shape: it is rebuilt, not trusted.
    hostile = {:crashed, @secret, [{Acker, :pick, [@secret], [file: ~c"a.ex", line: 1]}, @secret]}

    assert Redact.reason(hostile) ==
             {:crashed, :redacted, [{Acker, :pick, 1, [file: ~c"a.ex", line: 1]}, :redacted]}

    assert Redact.reason({:crashed, :x, [1 | 2]}) == {:crashed, :x, :redacted}
    assert Redact.safely(fn -> raise @secret end, :failed) == :failed
    assert Redact.safely(fn -> exit(@secret) end, :failed) == :failed

    assert catch_throw(Redact.guard(:state, fn -> throw({:reply, :ok, :state}) end)) ==
             {:reply, :ok, :state}

    assert {:stop, {:crashed, RuntimeError, _frames}, :state} =
             Redact.guard(:state, fn -> raise @secret end)

    # A callback's own exit with :shutdown is a crash, not the instance's stop.
    for reason <- [:shutdown, {:shutdown, :x}] do
      assert {:stop, stop, :state} = Redact.guard(:state, fn -> exit(reason) end)
      assert {:crashed, _tag, _frames} = stop
    end
  end

  # Every :logger event (the proc_lib crash report included, which Elixir's Logger leaves out), with its process.
  defmodule Handler do
    def log(%{meta: meta} = event, %{config: %{pid: pid}}) do
      text = IO.iodata_to_binary(:logger_formatter.format(event, %{}))
      send(pid, {:logged, Map.get(meta, :pid), text})
    end
  end

  # A plain GenServer, neither guarded nor sensitive: it shows what this OTP's reports print of a crash.
  defmodule Plain do
    use GenServer

    @impl true
    def init(state), do: {:ok, state}

    @impl true
    def handle_call(:crash, _from, state), do: {:reply, Map.fetch!(state, :missing), state}
  end

  # Throws from guarded callbacks, as the worker's processes run them.
  defmodule Thrower do
    use GenServer

    require Redact

    def start_link(_opts), do: GenServer.start_link(__MODULE__, %{})

    @impl true
    def init(state), do: {:ok, state}

    @impl true
    def handle_call(message, from, state),
      do: Redact.guard(state, fn -> call(message, from, state) end)

    @impl true
    def handle_info(message, state), do: Redact.guard(state, fn -> info(message, state) end)

    Redact.format_status(fn state -> map_size(state) end)

    defp call(:fine, _from, state), do: throw({:reply, :fine, state})
    defp call(value, _from, _state), do: throw(value)
    defp info(value, _state), do: throw(value)
  end

  # The crash and supervisor reports are SASL reports (domain [:otp, :sasl]). Elixir's Logger drops them with
  # primary filters unless `:handle_sasl_reports` is on, but an application may turn it on, or log through OTP's own
  # handler: the test lets every report through, so it sees what such an application would print.
  defp capture_reports do
    %{filters: filters, filter_default: filter_default} = :logger.get_primary_config()
    :ok = :logger.set_primary_config(:filters, [])
    :ok = :logger.set_primary_config(:filter_default, :log)
    handler = :"crash_log_#{System.unique_integer([:positive])}"
    :ok = :logger.add_handler(handler, Handler, %{config: %{pid: self()}})

    on_exit(fn ->
      :logger.remove_handler(handler)
      :logger.set_primary_config(:filters, filters)
      :logger.set_primary_config(:filter_default, filter_default)
    end)
