  # What was logged by the processes `pids`: everything until one text matches `wanted`, then 300 ms more.
  defp logged(pids, wanted, texts \\ []) do
    log = Enum.join(texts, "\n")
    wait = if log =~ wanted, do: 300, else: 3_000

    receive do
      {:logged, pid, text} ->
        logged(pids, wanted, if(pid in pids, do: [text | texts], else: texts))
    after
      wait -> log
    end
  end

  # Crashes `pid` on `crash` (a call) with `queued` (a call) waiting in its mailbox behind it.
  defp crash_with_queued(pid, crash, queued) do
