    Process.sleep(20)
    spawn(fn -> GenServer.call(pid, queued, :infinity) end)
    Process.sleep(20)
    :sys.resume(pid)
  end

  test "a worker process that crashes logs no token: not its state, mailbox, reason or frame arguments" do
    capture_reports()

    # The control: proc_lib's crash report of a plain process lists its mailbox; without it this test checks nothing.
    {:ok, plain} = GenServer.start(Plain, %{})
    crash_with_queued(plain, :crash, {:queued, "CONTROLMARKER"})
    control = logged([plain], "CONTROLMARKER")
    assert control =~ "terminating"
    assert control =~ "crasher", "no proc_lib crash report reached the test handler"

    assert control =~ "CONTROLMARKER",
           "the crash report of a plain process did not list its mailbox"

    name = :"redact_#{System.unique_integer([:positive])}"
    config = JoobQ.Config.new!(name: name, url: "https://x", token: "t0ken")
    {:ok, acker} = Acker.start_link(config)
    Process.unlink(acker)
    :ok = Acker.settle(name, %{"token" => @secret, "outcome" => "complete", "output" => nil})
    refute acker |> :sys.get_status() |> inspect() =~ @secret

    queued = %{"token" => "QUEUEDSECRET", "outcome" => "complete", "output" => "hunter2"}
    crash_with_queued(acker, {:unknown, %{"token" => @secret}}, {:settle, queued})
    log = logged([acker], "crasher")

