  test "a thrown return goes on to gen_server; any other throw is a stop that prints nothing of it" do
    capture_reports()
    {:ok, supervisor} = Supervisor.start_link([Thrower], strategy: :one_for_one)
    secret = %{"token" => "THROWSECRET"}
    child = fn -> supervisor |> Supervisor.which_children() |> hd() |> elem(1) end

    first = child.()
    assert GenServer.call(first, :fine) == :fine

    # The caller's exit is `{reason, {GenServer, :call, args}}`: the args are the caller's own; the reason is the
    # server's.
    {reason, {GenServer, :call, _args}} = catch_exit(GenServer.call(first, secret))
    refute inspect(reason) =~ "THROWSECRET"
    log = logged([first, supervisor], "child_terminated")
    assert log =~ "terminating"
    assert log =~ "crasher"
    assert log =~ "child_terminated"
    refute log =~ "THROWSECRET"

    Process.sleep(50)
    second = child.()
    assert second != first
    send(second, secret)
    log = logged([second, supervisor], "child_terminated")
    assert log =~ "terminating"
    assert log =~ "child_terminated"
    refute log =~ "THROWSECRET"
